// Sync the dither-kit registry into public/r/ at build time.
//
// Single source of truth: the Boring-Software-Inc/dither-kit repo, whose `r/`
// is generated by its own `build:registry`. We fetch it here instead of
// checking a hand-copied duplicate into this repo — a copy is exactly what
// drifts. See dither-kit/HOSTING.md: these files must be served from
// tripwire.sh/r/* for the CLI and `shadcn add` to resolve.
//
// Runs as `prebuild`/`predev`, so `public/r/` is a generated artifact (it is
// git-ignored). Override the source ref with DITHER_KIT_REF (defaults to main).

import { mkdir, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const REF = process.env.DITHER_KIT_REF ?? "main";
const BASE = `https://raw.githubusercontent.com/Boring-Software-Inc/dither-kit/${REF}/r`;
const OUT_DIR = fileURLToPath(new URL("../public/r/", import.meta.url));

/** Fetch a URL as text, failing loudly on a non-2xx so a broken build is
 * obvious rather than silently shipping a stale/partial registry. */
async function fetchText(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url} -> HTTP ${res.status}`);
  return res.text();
}

async function main() {
  // Fetch the index first, then every item it names — all into memory before
  // writing, so a mid-sync failure never leaves public/r/ half-written.
  const indexText = await fetchText(`${BASE}/registry.json`);
  const names = JSON.parse(indexText).items.map((it) => it.name);
  const items = await Promise.all(
    names.map(async (name) => ({ name, text: await fetchText(`${BASE}/${name}.json`) })),
  );

  await mkdir(OUT_DIR, { recursive: true });
  await writeFile(new URL("registry.json", `file://${OUT_DIR}`), indexText);
  await Promise.all(
    items.map((it) => writeFile(new URL(`${it.name}.json`, `file://${OUT_DIR}`), it.text)),
  );

  console.log(`registry: synced ${items.length} items + index from dither-kit@${REF}`);
}

main().catch((err) => {
  console.error(`registry sync failed: ${err.message}`);
  process.exit(1);
});
